content.content:
1	-- =============================================================
2	-- 高校志愿服务时长认证与公益画像数据分析系统
3	-- 脚本 2/4：建表脚本（16 张表 + 表/字段注释 + 索引）
4	-- 数据库类型：PostgreSQL 16+
5	-- =============================================================
6	--
7	-- 全局约定（源自知识库《全局技术规范》）：
8	--   1. 主键统一 id BIGSERIAL PRIMARY KEY（数据库自增，非雪花 ID）
9	--      对应 application.yml 中 mybatis-plus.global-config.db-config.id-type: auto
10	--   2. 命名统一 snake_case
11	--   3. 状态字段统一 VARCHAR 存【英文大写枚举码】，中文由 sys_dict 翻译
12	--   4. 时间字段统一 create_time / update_time，类型 TIMESTAMP
13	--   5. 时长字段统一 NUMERIC(10,1)，单位【小时】
14	--   6. 逻辑删除统一 deleted SMALLINT（0未删除 / 1已删除）
15	--      —— 仅用于"业务数据需要保留痕迹"的表；流水/日志/关联表不加（见各表说明）
16	--
17	-- 执行顺序：01_create_database.sql → 本脚本 → 03_init_data.sql → [04_demo_data.sql]
18	-- =============================================================
19	
20	SET client_encoding = 'UTF8';
21	
22	-- =============================================================
23	-- 清理旧表（使脚本可重复执行）
24	-- 依赖倒序删除，CASCADE 兜底；【会连同数据一起删除，生产环境切勿执行】
25	-- =============================================================
26	DROP TABLE IF EXISTS attachment         CASCADE;
27	DROP TABLE IF EXISTS operation_log      CASCADE;
28	DROP TABLE IF EXISTS sys_dict           CASCADE;
29	DROP TABLE IF EXISTS notification       CASCADE;
30	DROP TABLE IF EXISTS student_profile    CASCADE;
31	DROP TABLE IF EXISTS duration_audit     CASCADE;
32	DROP TABLE IF EXISTS service_duration   CASCADE;
33	DROP TABLE IF EXISTS attendance_record  CASCADE;
34	DROP TABLE IF EXISTS activity_signup    CASCADE;
35	DROP TABLE IF EXISTS volunteer_activity CASCADE;
36	DROP TABLE IF EXISTS activity_category  CASCADE;
37	DROP TABLE IF EXISTS org_info           CASCADE;
38	DROP TABLE IF EXISTS student_info       CASCADE;
39	DROP TABLE IF EXISTS sys_user_role      CASCADE;
40	DROP TABLE IF EXISTS sys_role           CASCADE;
41	DROP TABLE IF EXISTS sys_user           CASCADE;
42	
43	
44	-- =============================================================
45	-- 一、系统域（vcp-system）—— 8 张表
46	-- =============================================================
47	
48	-- -------------------------------------------------------------
49	-- 1. 用户表
50	-- -------------------------------------------------------------
51	CREATE TABLE sys_user (
52	    id          BIGSERIAL    PRIMARY KEY,
53	    username    VARCHAR(50)  NOT NULL UNIQUE,
54	    password    VARCHAR(100) NOT NULL,
55	    real_name   VARCHAR(50),
56	    phone       VARCHAR(20),
57	    email       VARCHAR(100),
58	    avatar      VARCHAR(255),
59	    status      SMALLINT     DEFAULT 1,
60	    deleted     SMALLINT     DEFAULT 0,
61	    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
62	    update_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP
63	);
64	
65	COMMENT ON TABLE  sys_user             IS '用户表';
66	COMMENT ON COLUMN sys_user.username    IS '用户名（登录账号，唯一）';
67	COMMENT ON COLUMN sys_user.password    IS '密码；初始化数据为明文，接入加密后请替换';
68	COMMENT ON COLUMN sys_user.real_name   IS '真实姓名';
69	COMMENT ON COLUMN sys_user.phone       IS '手机号';
70	COMMENT ON COLUMN sys_user.email       IS '邮箱';
71	COMMENT ON COLUMN sys_user.avatar      IS '头像地址';
72	COMMENT ON COLUMN sys_user.status      IS '状态：1启用，0禁用';
73	COMMENT ON COLUMN sys_user.deleted     IS '逻辑删除：0未删除，1已删除';
74	COMMENT ON COLUMN sys_user.create_time IS '创建时间';
75	COMMENT ON COLUMN sys_user.update_time IS '更新时间';
76	
77	-- -------------------------------------------------------------
78	-- 2. 角色表
79	-- -------------------------------------------------------------
80	CREATE TABLE sys_role (
81	    id          BIGSERIAL    PRIMARY KEY,
82	    role_code   VARCHAR(50)  NOT NULL UNIQUE,
83	    role_name   VARCHAR(50)  NOT NULL,
84	    remark      VARCHAR(255),
85	    deleted     SMALLINT     DEFAULT 0,
86	    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
87	    update_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP
88	);
89	
90	COMMENT ON TABLE  sys_role           IS '角色表';
91	COMMENT ON COLUMN sys_role.role_code IS '角色编码：STUDENT学生，ORG_ADMIN组织管理员，SCHOOL_ADMIN学校管理员';
92	COMMENT ON COLUMN sys_role.role_name IS '角色名称';
93	COMMENT ON COLUMN sys_role.remark    IS '备注';
94	COMMENT ON COLUMN sys_role.deleted   IS '逻辑删除：0未删除，1已删除';
95	
96	-- -------------------------------------------------------------
97	-- 3. 用户角色关联表
98	--    说明：关联表按物理删除设计，不加 deleted / update_time
99	-- -------------------------------------------------------------
100	CREATE TABLE sys_user_role (
101	    id          BIGSERIAL PRIMARY KEY,
102	    user_id     BIGINT    NOT NULL,
103	    role_id     BIGINT    NOT NULL,
104	    create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
105	    CONSTRAINT fk_user_role_user FOREIGN KEY (user_id) REFERENCES sys_user (id),
106	    CONSTRAINT fk_user_role_role FOREIGN KEY (role_id) REFERENCES sys_role (id),
107	    CONSTRAINT uk_user_role      UNIQUE (user_id, role_id)
108	);
109	
110	COMMENT ON TABLE  sys_user_role      IS '用户角色关联表';
111	COMMENT ON COLUMN sys_user_role.user_id IS '用户ID → sys_user.id';
112	COMMENT ON COLUMN sys_user_role.role_id IS '角色ID → sys_role.id';
113	
114	-- -------------------------------------------------------------
115	-- 4. 学生信息表
116	-- -------------------------------------------------------------
117	CREATE TABLE student_info (
118	    id                   BIGSERIAL    PRIMARY KEY,
119	    user_id              BIGINT       NOT NULL UNIQUE,
120	    student_no           VARCHAR(30)  NOT NULL UNIQUE,
121	    college              VARCHAR(100),
122	    major                VARCHAR(100),
123	    class_name           VARCHAR(100),
124	    total_duration       NUMERIC(10,1) DEFAULT 0,
125	    public_welfare_level VARCHAR(50),
126	    deleted              SMALLINT     DEFAULT 0,
127	    create_time          TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
128	    update_time          TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
129	    CONSTRAINT fk_student_user FOREIGN KEY (user_id) REFERENCES sys_user (id)
130	);
131	
132	COMMENT ON TABLE  student_info                      IS '学生信息表';
133	COMMENT ON COLUMN student_info.user_id              IS '关联用户ID → sys_user.id（一个用户对应一个学生档案）';
134	COMMENT ON COLUMN student_info.student_no           IS '学号（唯一）';
135	COMMENT ON COLUMN student_info.college              IS '学院';
136	COMMENT ON COLUMN student_info.major                IS '专业';
137	COMMENT ON COLUMN student_info.class_name           IS '班级';
138	COMMENT ON COLUMN student_info.total_duration       IS '累计有效志愿时长（小时）；由 service_duration 审核通过的数据汇总而来，是学院排名与画像的依据';
139	COMMENT ON COLUMN student_info.public_welfare_level IS '公益等级；【档位与阈值尚未确定，见 sql/README.md 待定项】';
140	COMMENT ON COLUMN student_info.deleted              IS '逻辑删除：0未删除，1已删除';
141	
142	-- -------------------------------------------------------------
143	-- 5. 数据字典表
144	-- -------------------------------------------------------------
145	CREATE TABLE sys_dict (
146	    id          BIGSERIAL    PRIMARY KEY,
147	    dict_type   VARCHAR(50)  NOT NULL,
148	    dict_key    VARCHAR(50)  NOT NULL,
149	    dict_value  VARCHAR(100) NOT NULL,
150	    sort        INT          DEFAULT 0,
151	    status      SMALLINT     DEFAULT 1,
152	    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
153	    update_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
154	    CONSTRAINT uk_dict_type_key UNIQUE (dict_type, dict_key)
155	);
156	
157	COMMENT ON TABLE  sys_dict           IS '数据字典表：状态英文码 → 中文展示值';
158	COMMENT ON COLUMN sys_dict.dict_type IS '字典类型：activity_status活动状态，signup_status报名状态，attendance_status签到状态，duration_status时长状态，org_status组织审核状态，notification_type通知类型，audit_action审核动作，attachment_biz_type附件业务类型';
159	COMMENT ON COLUMN sys_dict.dict_key  IS '字典键（入库的英文枚举码）';
160	COMMENT ON COLUMN sys_dict.dict_value IS '字典值（前端展示的中文）';
161	COMMENT ON COLUMN sys_dict.sort      IS '同类型内的排序';
162	COMMENT ON COLUMN sys_dict.status    IS '状态：1启用，0禁用';
163	
164	-- -------------------------------------------------------------
165	-- 6. 通知表
166	--    说明：通知用 is_read 表达"已读"，不做逻辑删除
167	-- -------------------------------------------------------------
168	CREATE TABLE notification (
169	    id          BIGSERIAL    PRIMARY KEY,
170	    user_id     BIGINT       NOT NULL,
171	    title       VARCHAR(200),
172	    content     TEXT,
173	    type        VARCHAR(50),
174	    is_read     BOOLEAN      DEFAULT FALSE,
175	    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
176	    CONSTRAINT fk_notification_user FOREIGN KEY (user_id) REFERENCES sys_user (id)
177	);
178	
179	COMMENT ON TABLE  notification         IS '通知表';
180	COMMENT ON COLUMN notification.user_id IS '接收人 → sys_user.id';
181	COMMENT ON COLUMN notification.title   IS '通知标题';
182	COMMENT ON COLUMN notification.content IS '通知内容';
183	COMMENT ON COLUMN notification.type    IS '通知类型：SIGNUP报名结果，DURATION时长审核，SYSTEM系统公告';
184	COMMENT ON COLUMN notification.is_read IS '是否已读：true已读，false未读';
185	
186	-- -------------------------------------------------------------
187	-- 7. 操作日志表
188	--    说明：日志按只追加设计，不加 deleted / update_time
189	-- -------------------------------------------------------------
190	CREATE TABLE operation_log (
191	    id          BIGSERIAL    PRIMARY KEY,
192	    user_id     BIGINT,
193	    username    VARCHAR(50),
194	    operation   VARCHAR(200),
195	    method      VARCHAR(200),
196	    params      TEXT,
197	    ip          VARCHAR(50),
198	    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP
199	);
200	
201	COMMENT ON TABLE  operation_log           IS '操作日志表';
202	COMMENT ON COLUMN operation_log.user_id   IS '操作人ID（未登录可为空）';
203	COMMENT ON COLUMN operation_log.username  IS '操作人用户名（冗余留存，用户改名后仍可追溯）';
204	COMMENT ON COLUMN operation_log.operation IS '操作描述';
205	COMMENT ON COLUMN operation_log.method    IS '调用的方法签名';
206	COMMENT ON COLUMN operation_log.params    IS '请求参数（建议脱敏后再落库）';
207	COMMENT ON COLUMN operation_log.ip        IS '来源IP';
208	
209	-- -------------------------------------------------------------
210	-- 8. 附件表
211	--    说明：biz_id 是多态外键（指向不同业务表），故不建物理外键
212	-- -------------------------------------------------------------
213	CREATE TABLE attachment (
214	    id          BIGSERIAL    PRIMARY KEY,
215	    biz_type    VARCHAR(50),
216	    biz_id      BIGINT,
217	    file_name   VARCHAR(255),
218	    file_url    VARCHAR(255),
219	    file_size   BIGINT,
220	    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP
221	);
222	
223	COMMENT ON TABLE  attachment           IS '附件表';
224	COMMENT ON COLUMN attachment.biz_type  IS '业务类型：ACTIVITY活动封面，ORG组织资质，AVATAR用户头像';
225	COMMENT ON COLUMN attachment.biz_id    IS '业务ID（多态，不加外键约束）';
226	COMMENT ON COLUMN attachment.file_name IS '原始文件名';
227	COMMENT ON COLUMN attachment.file_url  IS '访问地址';
228	COMMENT ON COLUMN attachment.file_size IS '文件大小（字节）';
229	
230	
231	-- =============================================================
232	-- 二、志愿组织域（vcp-org）—— 1 张表
233	-- =============================================================
234	
235	-- -------------------------------------------------------------
236	-- 9. 志愿组织信息表
237	-- -------------------------------------------------------------
238	CREATE TABLE org_info (
239	    id              BIGSERIAL    PRIMARY KEY,
240	    contact_user_id BIGINT,
241	    org_name        VARCHAR(100) NOT NULL,
242	    org_type        VARCHAR(50),
243	    contact_name    VARCHAR(50),
244	    phone           VARCHAR(20),
245	    email           VARCHAR(100),
246	    description     TEXT,
247	    status          VARCHAR(20)  DEFAULT 'PENDING',
248	    deleted         SMALLINT     DEFAULT 0,
249	    create_time     TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
250	    update_time     TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
251	    CONSTRAINT fk_org_contact_user FOREIGN KEY (contact_user_id) REFERENCES sys_user (id)
252	);
253	
254	COMMENT ON TABLE  org_info                 IS '志愿组织信息表';
255	COMMENT ON COLUMN org_info.contact_user_id IS '组织管理员账号ID → sys_user.id';
256	COMMENT ON COLUMN org_info.org_name        IS '组织名称';
257	COMMENT ON COLUMN org_info.org_type        IS '组织类型：学院组织、社会团体等';
258	COMMENT ON COLUMN org_info.contact_name    IS '负责人姓名';
259	COMMENT ON COLUMN org_info.phone           IS '联系电话';
260	COMMENT ON COLUMN org_info.email           IS '联系邮箱';
261	COMMENT ON COLUMN org_info.description     IS '组织简介';
262	COMMENT ON COLUMN org_info.status          IS '审核状态：PENDING待审核，APPROVED已通过，REJECTED已驳回（由学校管理员审核）';
263	COMMENT ON COLUMN org_info.deleted         IS '逻辑删除：0未删除，1已删除';
264	
265	
266	-- =============================================================
267	-- 三、志愿服务活动域（vcp-volunteer）—— 4 张表
268	-- =============================================================
269	
270	-- -------------------------------------------------------------
271	-- 10. 活动分类表
272	-- -------------------------------------------------------------
273	CREATE TABLE activity_category (
274	    id            BIGSERIAL   PRIMARY KEY,
275	    category_name VARCHAR(50) NOT NULL,
276	    sort          INT         DEFAULT 0,
277	    status        SMALLINT    DEFAULT 1,
278	    deleted       SMALLINT    DEFAULT 0,
279	    create_time   TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
280	    update_time   TIMESTAMP   DEFAULT CURRENT_TIMESTAMP
281	);
282	
283	COMMENT ON TABLE  activity_category               IS '活动分类表';
284	COMMENT ON COLUMN activity_category.category_name IS '分类名称';
285	COMMENT ON COLUMN activity_category.sort          IS '排序（升序）';
286	COMMENT ON COLUMN activity_category.status        IS '状态：1启用，0禁用';
287	COMMENT ON COLUMN activity_category.deleted       IS '逻辑删除：0未删除，1已删除';
288	
289	-- -------------------------------------------------------------
290	-- 11. 志愿活动表
291	-- -------------------------------------------------------------
292	CREATE TABLE volunteer_activity (
293	    id           BIGSERIAL     PRIMARY KEY,
294	    title        VARCHAR(200)  NOT NULL,
295	    category_id  BIGINT,
296	    org_id       BIGINT,
297	    start_time   TIMESTAMP,
298	    end_time     TIMESTAMP,
299	    location     VARCHAR(200),
300	    max_count    INT           DEFAULT 0,
301	    signed_count INT           DEFAULT 0,
302	    duration     NUMERIC(10,1) DEFAULT 0,
303	    status       VARCHAR(20)   DEFAULT 'DRAFT',
304	    cover        VARCHAR(255),
305	    description  TEXT,
306	    deleted      SMALLINT      DEFAULT 0,
307	    create_time  TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
308	    update_time  TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
309	    CONSTRAINT fk_activity_category FOREIGN KEY (category_id) REFERENCES activity_category (id),
310	    CONSTRAINT fk_activity_org      FOREIGN KEY (org_id)      REFERENCES org_info (id)
311	);
312	
313	COMMENT ON TABLE  volunteer_activity              IS '志愿活动表';
314	COMMENT ON COLUMN volunteer_activity.title        IS '活动名称';
315	COMMENT ON COLUMN volunteer_activity.category_id  IS '活动分类 → activity_category.id';
316	COMMENT ON COLUMN volunteer_activity.org_id       IS '发布组织 → org_info.id';
317	COMMENT ON COLUMN volunteer_activity.start_time   IS '开始时间';
318	COMMENT ON COLUMN volunteer_activity.end_time     IS '结束时间';
319	COMMENT ON COLUMN volunteer_activity.location     IS '活动地点';
320	COMMENT ON COLUMN volunteer_activity.max_count    IS '人数上限；0 表示不限';
321	COMMENT ON COLUMN volunteer_activity.signed_count IS '已报名人数（冗余计数，由报名审核通过/取消时维护，用于快速判断是否报满）';
322	COMMENT ON COLUMN volunteer_activity.duration     IS '预计志愿时长（小时）';
323	COMMENT ON COLUMN volunteer_activity.status       IS '活动状态：DRAFT草稿，PUBLISHED已发布，CLOSED已结束，CANCELED已取消';
324	COMMENT ON COLUMN volunteer_activity.cover        IS '封面图地址';
325	COMMENT ON COLUMN volunteer_activity.description  IS '活动详情';
326	COMMENT ON COLUMN volunteer_activity.deleted      IS '逻辑删除：0未删除，1已删除';
327	
328	-- -------------------------------------------------------------
329	-- 12. 活动报名表
330	-- -------------------------------------------------------------
331	CREATE TABLE activity_signup (
332	    id           BIGSERIAL    PRIMARY KEY,
333	    activity_id  BIGINT       NOT NULL,
334	    student_id   BIGINT       NOT NULL,
335	    signup_time  TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
336	    status       VARCHAR(20)  DEFAULT 'PENDING',
337	    audit_remark VARCHAR(255),
338	    audit_user_id BIGINT,
339	    audit_time   TIMESTAMP,
340	    deleted      SMALLINT     DEFAULT 0,
341	    create_time  TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
342	    update_time  TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
343	    CONSTRAINT fk_signup_activity   FOREIGN KEY (activity_id)   REFERENCES volunteer_activity (id),
344	    CONSTRAINT fk_signup_student    FOREIGN KEY (student_id)    REFERENCES student_info (id),
345	    CONSTRAINT fk_signup_audit_user FOREIGN KEY (audit_user_id) REFERENCES sys_user (id),
346	    CONSTRAINT uk_activity_student  UNIQUE (activity_id, student_id)
347	);
348	
349	COMMENT ON TABLE  activity_signup              IS '活动报名表';
350	COMMENT ON COLUMN activity_signup.activity_id  IS '活动ID → volunteer_activity.id';
351	COMMENT ON COLUMN activity_signup.student_id   IS '学生ID → student_info.id（注意：是学生档案ID，不是 sys_user.id）';
352	COMMENT ON COLUMN activity_signup.signup_time  IS '报名时间';
353	COMMENT ON COLUMN activity_signup.status       IS '报名状态：PENDING待审核，APPROVED已通过，REJECTED已驳回，CANCELED已取消，COMPLETED已完成';
354	COMMENT ON COLUMN activity_signup.audit_remark IS '审核意见';
355	COMMENT ON COLUMN activity_signup.audit_user_id IS '审核人 → sys_user.id（组织管理员）';
356	COMMENT ON COLUMN activity_signup.audit_time   IS '审核时间';
357	COMMENT ON COLUMN activity_signup.deleted      IS '逻辑删除：0未删除，1已删除';
358	
359	-- -------------------------------------------------------------
360	-- 13. 签到签退记录表
361	--     说明：signup_id 唯一 → 一条报名最多一条签到记录
362	-- -------------------------------------------------------------
363	CREATE TABLE attendance_record (
364	    id            BIGSERIAL   PRIMARY KEY,
365	    signup_id     BIGINT      NOT NULL UNIQUE,
366	    sign_in_time  TIMESTAMP,
367	    sign_out_time TIMESTAMP,
368	    status        VARCHAR(20) DEFAULT 'NOT_SIGNED',
369	    remark        VARCHAR(255),
370	    deleted       SMALLINT    DEFAULT 0,
371	    create_time   TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
372	    update_time   TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
373	    CONSTRAINT fk_attendance_signup FOREIGN KEY (signup_id) REFERENCES activity_signup (id)
374	);
375	
376	COMMENT ON TABLE  attendance_record               IS '签到签退记录表';
377	COMMENT ON COLUMN attendance_record.signup_id     IS '报名ID → activity_signup.id（唯一，一条报名对应一条签到记录）';
378	COMMENT ON COLUMN attendance_record.sign_in_time  IS '签到时间';
379	COMMENT ON COLUMN attendance_record.sign_out_time IS '签退时间';
380	COMMENT ON COLUMN attendance_record.status        IS '签到状态：NOT_SIGNED未签到，SIGNED_IN已签到，SIGNED_OUT已签退，ABNORMAL异常，ABSENT缺勤';
381	COMMENT ON COLUMN attendance_record.remark        IS '备注（异常原因等）';
382	COMMENT ON COLUMN attendance_record.deleted       IS '逻辑删除：0未删除，1已删除';
383	
384	
385	-- =============================================================
386	-- 四、时长认证域（vcp-certification）—— 2 张表
387	-- =============================================================
388	
389	-- -------------------------------------------------------------
390	-- 14. 服务时长表
391	-- -------------------------------------------------------------
392	CREATE TABLE service_duration (
393	    id            BIGSERIAL     PRIMARY KEY,
394	    signup_id     BIGINT        NOT NULL UNIQUE,
395	    activity_id   BIGINT        NOT NULL,
396	    student_id    BIGINT        NOT NULL,
397	    duration      NUMERIC(10,1) DEFAULT 0,
398	    status        VARCHAR(20)   DEFAULT 'PENDING_SUBMIT',
399	    submit_time   TIMESTAMP,
400	    audit_user_id BIGINT,
401	    audit_time    TIMESTAMP,
402	    audit_remark  VARCHAR(255),
403	    deleted       SMALLINT      DEFAULT 0,
404	    create_time   TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
405	    update_time   TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
406	    CONSTRAINT fk_duration_signup    FOREIGN KEY (signup_id)   REFERENCES activity_signup (id),
407	    CONSTRAINT fk_duration_activity  FOREIGN KEY (activity_id) REFERENCES volunteer_activity (id),
408	    CONSTRAINT fk_duration_student   FOREIGN KEY (student_id)  REFERENCES student_info (id),
409	    CONSTRAINT fk_duration_audit_user FOREIGN KEY (audit_user_id) REFERENCES sys_user (id)
410	);
411	
412	COMMENT ON TABLE  service_duration               IS '服务时长表';
413	COMMENT ON COLUMN service_duration.signup_id     IS '报名ID → activity_signup.id（唯一，一条报名对应一条时长记录）';
414	COMMENT ON COLUMN service_duration.activity_id   IS '活动ID → volunteer_activity.id（冗余，便于按活动统计）';
415	COMMENT ON COLUMN service_duration.student_id    IS '学生ID → student_info.id（冗余，便于按学生/学院统计）';
416	COMMENT ON COLUMN service_duration.duration      IS '实际服务时长（小时）；由组织管理员依据签到签退记录提交';
417	COMMENT ON COLUMN service_duration.status        IS '时长状态：PENDING_SUBMIT待提交，PENDING_AUDIT待审核，APPROVED已通过，REJECTED已驳回（由学校管理员终审）';
418	COMMENT ON COLUMN service_duration.submit_time   IS '提交时间';
419	COMMENT ON COLUMN service_duration.audit_user_id IS '审核人 → sys_user.id（学校管理员）';
420	COMMENT ON COLUMN service_duration.audit_time    IS '审核时间';
421	COMMENT ON COLUMN service_duration.audit_remark  IS '审核意见（驳回原因）';
422	COMMENT ON COLUMN service_duration.deleted       IS '逻辑删除：0未删除，1已删除';
423	
424	-- -------------------------------------------------------------
425	-- 15. 时长审核记录表
426	--     说明：审核流水按只追加设计，不加 deleted / update_time
427	-- -------------------------------------------------------------
428	CREATE TABLE duration_audit (
429	    id          BIGSERIAL   PRIMARY KEY,
430	    duration_id BIGINT      NOT NULL,
431	    auditor_id  BIGINT,
432	    action      VARCHAR(20),
433	    remark      VARCHAR(255),
434	    create_time TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
435	    CONSTRAINT fk_audit_duration FOREIGN KEY (duration_id) REFERENCES service_duration (id),
436	    CONSTRAINT fk_audit_auditor  FOREIGN KEY (auditor_id)  REFERENCES sys_user (id)
437	);
438	
439	COMMENT ON TABLE  duration_audit             IS '时长审核记录表（每次提交/审核动作留痕）';
440	COMMENT ON COLUMN duration_audit.duration_id IS '时长记录ID → service_duration.id';
441	COMMENT ON COLUMN duration_audit.auditor_id  IS '操作人 → sys_user.id';
442	COMMENT ON COLUMN duration_audit.action      IS '审核动作：SUBMIT提交，APPROVE通过，REJECT驳回（注意与状态值的 APPROVED/REJECTED 不同形）';
443	COMMENT ON COLUMN duration_audit.remark      IS '备注';
444	
445	
446	-- =============================================================
447	-- 五、公益画像域（vcp-portrait）—— 1 张表
448	-- =============================================================
449	
450	-- -------------------------------------------------------------
451	-- 16. 学生公益画像表
452	-- -------------------------------------------------------------
453	CREATE TABLE student_profile (
454	    id                  BIGSERIAL     PRIMARY KEY,
455	    student_id          BIGINT        NOT NULL UNIQUE,
456	    total_activities    INT           DEFAULT 0,
457	    total_duration      NUMERIC(10,1) DEFAULT 0,
458	    category_preference VARCHAR(255),
459	    tags                VARCHAR(255),
460	    portrait_desc       TEXT,
461	    create_time         TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
462	    update_time         TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
463	    CONSTRAINT fk_profile_student FOREIGN KEY (student_id) REFERENCES student_info (id)
464	);
465	
466	COMMENT ON TABLE  student_profile                     IS '学生公益画像表（每个学生一行，由定时/手动任务重算）';
467	COMMENT ON COLUMN student_profile.student_id          IS '学生ID → student_info.id（唯一）';
468	COMMENT ON COLUMN student_profile.total_activities    IS '参与活动次数（按审核通过的报名计）';
469	COMMENT ON COLUMN student_profile.total_duration      IS '累计志愿时长（小时）；权威值在 student_info.total_duration，此处为画像快照，见 README 待定项';
470	COMMENT ON COLUMN student_profile.category_preference IS '偏好活动类型（参与最多的分类名）';
471	COMMENT ON COLUMN student_profile.tags                IS '公益标签，逗号分隔（如"热心志愿者,校园服务型"）；【判定规则尚未确定，见 README 待定项】';
472	COMMENT ON COLUMN student_profile.portrait_desc       IS '画像描述文本';
473	
474	
475	-- =============================================================
476	-- 六、索引
477	-- =============================================================
478	--
479	-- 设计说明（与最初 AI 生成的脚本相比做了删减与补充，理由见 sql/README.md）：
480	--   · 删除了被 UNIQUE 约束覆盖的冗余索引：sys_user(username)、sys_role(role_code)、
481	--     student_info(student_no)
482	--   · 删除了被 uk_activity_student(activity_id, student_id) 最左前缀覆盖的
483	--     activity_signup(activity_id)
484	--   · attendance_record(signup_id) 同理被其 UNIQUE 约束覆盖，无需另建
485	--   · 补上知识库《全局技术规范》建议的复合索引，以及看板统计所需索引
486	--
487	-- 被删除的索引并非"错误"，只是重复占用空间与写入开销；如需与旧脚本保持一致可自行加回。
488	-- -------------------------------------------------------------
489	
490	-- 活动：按状态筛选、按开始时间排序（活动列表页）
491	CREATE INDEX idx_activity_status     ON volunteer_activity (status);
492	CREATE INDEX idx_activity_start_time ON volunteer_activity (start_time);
493	-- 活动：组织端"本组织的活动"按状态筛选
494	CREATE INDEX idx_activity_org_status ON volunteer_activity (org_id, status);
495	-- 活动：看板"本月新增活动数"与活动数量趋势图
496	CREATE INDEX idx_activity_create_time ON volunteer_activity (create_time);
497	
498	-- 报名：学生端"我的报名"按状态筛选（student_id 为最左前缀，同时覆盖仅按 student_id 的查询）
499	CREATE INDEX idx_signup_student_status ON activity_signup (student_id, status);
500	
501	-- 时长：学校端"待审核时长"列表
502	CREATE INDEX idx_duration_status         ON service_duration (status);
503	-- 时长：学生端"我的时长"按状态筛选
504	CREATE INDEX idx_duration_student_status ON service_duration (student_id, status);
505	-- 时长：看板"各学院志愿时长排名"需要按学院分组，先按学生定位
506	CREATE INDEX idx_duration_activity       ON service_duration (activity_id);
507	
508	-- 学生：学院排名与学院维度统计按学院分组
509	CREATE INDEX idx_student_college ON student_info (college);
510	
511	-- 通知：学生端"我的通知"与未读数
512	CREATE INDEX idx_notification_user ON notification (user_id);

file.content:
-- =============================================================
-- 高校志愿服务时长认证与公益画像数据分析系统
-- 脚本 2/4：建表脚本（16 张表 + 表/字段注释 + 索引）
-- 数据库类型：PostgreSQL 16+
-- =============================================================
--
-- 全局约定（源自知识库《全局技术规范》）：
--   1. 主键统一 id BIGSERIAL PRIMARY KEY（数据库自增，非雪花 ID）
--      对应 application.yml 中 mybatis-plus.global-config.db-config.id-type: auto
--   2. 命名统一 snake_case
--   3. 状态字段统一 VARCHAR 存【英文大写枚举码】，中文由 sys_dict 翻译
--   4. 时间字段统一 create_time / update_time，类型 TIMESTAMP
--   5. 时长字段统一 NUMERIC(10,1)，单位【小时】
--   6. 逻辑删除统一 deleted SMALLINT（0未删除 / 1已删除）
--      —— 仅用于"业务数据需要保留痕迹"的表；流水/日志/关联表不加（见各表说明）
--
-- 执行顺序：01_create_database.sql → 本脚本 → 03_init_data.sql → [04_demo_data.sql]
-- =============================================================

SET client_encoding = 'UTF8';

-- =============================================================
-- 清理旧表（使脚本可重复执行）
-- 依赖倒序删除，CASCADE 兜底；【会连同数据一起删除，生产环境切勿执行】
-- =============================================================
DROP TABLE IF EXISTS attachment         CASCADE;
DROP TABLE IF EXISTS operation_log      CASCADE;
DROP TABLE IF EXISTS sys_dict           CASCADE;
DROP TABLE IF EXISTS notification       CASCADE;
DROP TABLE IF EXISTS student_profile    CASCADE;
DROP TABLE IF EXISTS duration_audit     CASCADE;
DROP TABLE IF EXISTS service_duration   CASCADE;
DROP TABLE IF EXISTS attendance_record  CASCADE;
DROP TABLE IF EXISTS activity_signup    CASCADE;
DROP TABLE IF EXISTS volunteer_activity CASCADE;
DROP TABLE IF EXISTS activity_category  CASCADE;
DROP TABLE IF EXISTS org_info           CASCADE;
DROP TABLE IF EXISTS student_info       CASCADE;
DROP TABLE IF EXISTS sys_user_role      CASCADE;
DROP TABLE IF EXISTS sys_role           CASCADE;
DROP TABLE IF EXISTS sys_user           CASCADE;


-- =============================================================
-- 一、系统域（vcp-system）—— 8 张表
-- =============================================================

-- -------------------------------------------------------------
-- 1. 用户表
-- -------------------------------------------------------------
CREATE TABLE sys_user (
    id          BIGSERIAL    PRIMARY KEY,
    username    VARCHAR(50)  NOT NULL UNIQUE,
    password    VARCHAR(100) NOT NULL,
    real_name   VARCHAR(50),
    phone       VARCHAR(20),
    email       VARCHAR(100),
    avatar      VARCHAR(255),
    status      SMALLINT     DEFAULT 1,
    deleted     SMALLINT     DEFAULT 0,
    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE  sys_user             IS '用户表';
COMMENT ON COLUMN sys_user.username    IS '用户名（登录账号，唯一）';
COMMENT ON COLUMN sys_user.password    IS '密码；初始化数据为明文，接入加密后请替换';
COMMENT ON COLUMN sys_user.real_name   IS '真实姓名';
COMMENT ON COLUMN sys_user.phone       IS '手机号';
COMMENT ON COLUMN sys_user.email       IS '邮箱';
COMMENT ON COLUMN sys_user.avatar      IS '头像地址';
COMMENT ON COLUMN sys_user.status      IS '状态：1启用，0禁用';
COMMENT ON COLUMN sys_user.deleted     IS '逻辑删除：0未删除，1已删除';
COMMENT ON COLUMN sys_user.create_time IS '创建时间';
COMMENT ON COLUMN sys_user.update_time IS '更新时间';

-- -------------------------------------------------------------
-- 2. 角色表
-- -------------------------------------------------------------
CREATE TABLE sys_role (
    id          BIGSERIAL    PRIMARY KEY,
    role_code   VARCHAR(50)  NOT NULL UNIQUE,
    role_name   VARCHAR(50)  NOT NULL,
    remark      VARCHAR(255),
    deleted     SMALLINT     DEFAULT 0,
    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE  sys_role           IS '角色表';
COMMENT ON COLUMN sys_role.role_code IS '角色编码：STUDENT学生，ORG_ADMIN组织管理员，SCHOOL_ADMIN学校管理员';
COMMENT ON COLUMN sys_role.role_name IS '角色名称';
COMMENT ON COLUMN sys_role.remark    IS '备注';
COMMENT ON COLUMN sys_role.deleted   IS '逻辑删除：0未删除，1已删除';

-- -------------------------------------------------------------
-- 3. 用户角色关联表
--    说明：关联表按物理删除设计，不加 deleted / update_time
-- -------------------------------------------------------------
CREATE TABLE sys_user_role (
    id          BIGSERIAL PRIMARY KEY,
    user_id     BIGINT    NOT NULL,
    role_id     BIGINT    NOT NULL,
    create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_user_role_user FOREIGN KEY (user_id) REFERENCES sys_user (id),
    CONSTRAINT fk_user_role_role FOREIGN KEY (role_id) REFERENCES sys_role (id),
    CONSTRAINT uk_user_role      UNIQUE (user_id, role_id)
);

COMMENT ON TABLE  sys_user_role      IS '用户角色关联表';
COMMENT ON COLUMN sys_user_role.user_id IS '用户ID → sys_user.id';
COMMENT ON COLUMN sys_user_role.role_id IS '角色ID → sys_role.id';

-- -------------------------------------------------------------
-- 4. 学生信息表
-- -------------------------------------------------------------
CREATE TABLE student_info (
    id                   BIGSERIAL    PRIMARY KEY,
    user_id              BIGINT       NOT NULL UNIQUE,
    student_no           VARCHAR(30)  NOT NULL UNIQUE,
    college              VARCHAR(100),
    major                VARCHAR(100),
    class_name           VARCHAR(100),
    total_duration       NUMERIC(10,1) DEFAULT 0,
    public_welfare_level VARCHAR(50),
    deleted              SMALLINT     DEFAULT 0,
    create_time          TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    update_time          TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_student_user FOREIGN KEY (user_id) REFERENCES sys_user (id)
);

COMMENT ON TABLE  student_info                      IS '学生信息表';
COMMENT ON COLUMN student_info.user_id              IS '关联用户ID → sys_user.id（一个用户对应一个学生档案）';
COMMENT ON COLUMN student_info.student_no           IS '学号（唯一）';
COMMENT ON COLUMN student_info.college              IS '学院';
COMMENT ON COLUMN student_info.major                IS '专业';
COMMENT ON COLUMN student_info.class_name           IS '班级';
COMMENT ON COLUMN student_info.total_duration       IS '累计有效志愿时长（小时）；由 service_duration 审核通过的数据汇总而来，是学院排名与画像的依据';
COMMENT ON COLUMN student_info.public_welfare_level IS '公益等级；【档位与阈值尚未确定，见 sql/README.md 待定项】';
COMMENT ON COLUMN student_info.deleted              IS '逻辑删除：0未删除，1已删除';

-- -------------------------------------------------------------
-- 5. 数据字典表
-- -------------------------------------------------------------
CREATE TABLE sys_dict (
    id          BIGSERIAL    PRIMARY KEY,
    dict_type   VARCHAR(50)  NOT NULL,
    dict_key    VARCHAR(50)  NOT NULL,
    dict_value  VARCHAR(100) NOT NULL,
    sort        INT          DEFAULT 0,
    status      SMALLINT     DEFAULT 1,
    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_dict_type_key UNIQUE (dict_type, dict_key)
);

COMMENT ON TABLE  sys_dict           IS '数据字典表：状态英文码 → 中文展示值';
COMMENT ON COLUMN sys_dict.dict_type IS '字典类型：activity_status活动状态，signup_status报名状态，attendance_status签到状态，duration_status时长状态，org_status组织审核状态，notification_type通知类型，audit_action审核动作，attachment_biz_type附件业务类型';
COMMENT ON COLUMN sys_dict.dict_key  IS '字典键（入库的英文枚举码）';
COMMENT ON COLUMN sys_dict.dict_value IS '字典值（前端展示的中文）';
COMMENT ON COLUMN sys_dict.sort      IS '同类型内的排序';
COMMENT ON COLUMN sys_dict.status    IS '状态：1启用，0禁用';

-- -------------------------------------------------------------
-- 6. 通知表
--    说明：通知用 is_read 表达"已读"，不做逻辑删除
-- -------------------------------------------------------------
CREATE TABLE notification (
    id          BIGSERIAL    PRIMARY KEY,
    user_id     BIGINT       NOT NULL,
    title       VARCHAR(200),
    content     TEXT,
    type        VARCHAR(50),
    is_read     BOOLEAN      DEFAULT FALSE,
    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_notification_user FOREIGN KEY (user_id) REFERENCES sys_user (id)
);

COMMENT ON TABLE  notification         IS '通知表';
COMMENT ON COLUMN notification.user_id IS '接收人 → sys_user.id';
COMMENT ON COLUMN notification.title   IS '通知标题';
COMMENT ON COLUMN notification.content IS '通知内容';
COMMENT ON COLUMN notification.type    IS '通知类型：SIGNUP报名结果，DURATION时长审核，SYSTEM系统公告';
COMMENT ON COLUMN notification.is_read IS '是否已读：true已读，false未读';

-- -------------------------------------------------------------
-- 7. 操作日志表
--    说明：日志按只追加设计，不加 deleted / update_time
-- -------------------------------------------------------------
CREATE TABLE operation_log (
    id          BIGSERIAL    PRIMARY KEY,
    user_id     BIGINT,
    username    VARCHAR(50),
    operation   VARCHAR(200),
    method      VARCHAR(200),
    params      TEXT,
    ip          VARCHAR(50),
    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE  operation_log           IS '操作日志表';
COMMENT ON COLUMN operation_log.user_id   IS '操作人ID（未登录可为空）';
COMMENT ON COLUMN operation_log.username  IS '操作人用户名（冗余留存，用户改名后仍可追溯）';
COMMENT ON COLUMN operation_log.operation IS '操作描述';
COMMENT ON COLUMN operation_log.method    IS '调用的方法签名';
COMMENT ON COLUMN operation_log.params    IS '请求参数（建议脱敏后再落库）';
COMMENT ON COLUMN operation_log.ip        IS '来源IP';

-- -------------------------------------------------------------
-- 8. 附件表
--    说明：biz_id 是多态外键（指向不同业务表），故不建物理外键
-- -------------------------------------------------------------
CREATE TABLE attachment (
    id          BIGSERIAL    PRIMARY KEY,
    biz_type    VARCHAR(50),
    biz_id      BIGINT,
    file_name   VARCHAR(255),
    file_url    VARCHAR(255),
    file_size   BIGINT,
    create_time TIMESTAMP    DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE  attachment           IS '附件表';
COMMENT ON COLUMN attachment.biz_type  IS '业务类型：ACTIVITY活动封面，ORG组织资质，AVATAR用户头像';
COMMENT ON COLUMN attachment.biz_id    IS '业务ID（多态，不加外键约束）';
COMMENT ON COLUMN attachment.file_name IS '原始文件名';
COMMENT ON COLUMN attachment.file_url  IS '访问地址';
COMMENT ON COLUMN attachment.file_size IS '文件大小（字节）';


-- =============================================================
-- 二、志愿组织域（vcp-org）—— 1 张表
-- =============================================================

-- -------------------------------------------------------------
-- 9. 志愿组织信息表
-- -------------------------------------------------------------
CREATE TABLE org_info (
    id              BIGSERIAL    PRIMARY KEY,
    contact_user_id BIGINT,
    org_name        VARCHAR(100) NOT NULL,
    org_type        VARCHAR(50),
    contact_name    VARCHAR(50),
    phone           VARCHAR(20),
    email           VARCHAR(100),
    description     TEXT,
    status          VARCHAR(20)  DEFAULT 'PENDING',
    deleted         SMALLINT     DEFAULT 0,
    create_time     TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    update_time     TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_org_contact_user FOREIGN KEY (contact_user_id) REFERENCES sys_user (id)
);

COMMENT ON TABLE  org_info                 IS '志愿组织信息表';
COMMENT ON COLUMN org_info.contact_user_id IS '组织管理员账号ID → sys_user.id';
COMMENT ON COLUMN org_info.org_name        IS '组织名称';
COMMENT ON COLUMN org_info.org_type        IS '组织类型：学院组织、社会团体等';
COMMENT ON COLUMN org_info.contact_name    IS '负责人姓名';
COMMENT ON COLUMN org_info.phone           IS '联系电话';
COMMENT ON COLUMN org_info.email           IS '联系邮箱';
COMMENT ON COLUMN org_info.description     IS '组织简介';
COMMENT ON COLUMN org_info.status          IS '审核状态：PENDING待审核，APPROVED已通过，REJECTED已驳回（由学校管理员审核）';
COMMENT ON COLUMN org_info.deleted         IS '逻辑删除：0未删除，1已删除';


-- =============================================================
-- 三、志愿服务活动域（vcp-volunteer）—— 4 张表
-- =============================================================

-- -------------------------------------------------------------
-- 10. 活动分类表
-- -------------------------------------------------------------
CREATE TABLE activity_category (
    id            BIGSERIAL   PRIMARY KEY,
    category_name VARCHAR(50) NOT NULL,
    sort          INT         DEFAULT 0,
    status        SMALLINT    DEFAULT 1,
    deleted       SMALLINT    DEFAULT 0,
    create_time   TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    update_time   TIMESTAMP   DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE  activity_category               IS '活动分类表';
COMMENT ON COLUMN activity_category.category_name IS '分类名称';
COMMENT ON COLUMN activity_category.sort          IS '排序（升序）';
COMMENT ON COLUMN activity_category.status        IS '状态：1启用，0禁用';
COMMENT ON COLUMN activity_category.deleted       IS '逻辑删除：0未删除，1已删除';

-- -------------------------------------------------------------
-- 11. 志愿活动表
-- -------------------------------------------------------------
CREATE TABLE volunteer_activity (
    id           BIGSERIAL     PRIMARY KEY,
    title        VARCHAR(200)  NOT NULL,
    category_id  BIGINT,
    org_id       BIGINT,
    start_time   TIMESTAMP,
    end_time     TIMESTAMP,
    location     VARCHAR(200),
    max_count    INT           DEFAULT 0,
    signed_count INT           DEFAULT 0,
    duration     NUMERIC(10,1) DEFAULT 0,
    status       VARCHAR(20)   DEFAULT 'DRAFT',
    cover        VARCHAR(255),
    description  TEXT,
    deleted      SMALLINT      DEFAULT 0,
    create_time  TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    update_time  TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_activity_category FOREIGN KEY (category_id) REFERENCES activity_category (id),
    CONSTRAINT fk_activity_org      FOREIGN KEY (org_id)      REFERENCES org_info (id)
);

COMMENT ON TABLE  volunteer_activity              IS '志愿活动表';
COMMENT ON COLUMN volunteer_activity.title        IS '活动名称';
COMMENT ON COLUMN volunteer_activity.category_id  IS '活动分类 → activity_category.id';
COMMENT ON COLUMN volunteer_activity.org_id       IS '发布组织 → org_info.id';
COMMENT ON COLUMN volunteer_activity.start_time   IS '开始时间';
COMMENT ON COLUMN volunteer_activity.end_time     IS '结束时间';
COMMENT ON COLUMN volunteer_activity.location     IS '活动地点';
COMMENT ON COLUMN volunteer_activity.max_count    IS '人数上限；0 表示不限';
COMMENT ON COLUMN volunteer_activity.signed_count IS '已报名人数（冗余计数，由报名审核通过/取消时维护，用于快速判断是否报满）';
COMMENT ON COLUMN volunteer_activity.duration     IS '预计志愿时长（小时）';
COMMENT ON COLUMN volunteer_activity.status       IS '活动状态：DRAFT草稿，PUBLISHED已发布，CLOSED已结束，CANCELED已取消';
COMMENT ON COLUMN volunteer_activity.cover        IS '封面图地址';
COMMENT ON COLUMN volunteer_activity.description  IS '活动详情';
COMMENT ON COLUMN volunteer_activity.deleted      IS '逻辑删除：0未删除，1已删除';

-- -------------------------------------------------------------
-- 12. 活动报名表
-- -------------------------------------------------------------
CREATE TABLE activity_signup (
    id           BIGSERIAL    PRIMARY KEY,
    activity_id  BIGINT       NOT NULL,
    student_id   BIGINT       NOT NULL,
    signup_time  TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    status       VARCHAR(20)  DEFAULT 'PENDING',
    audit_remark VARCHAR(255),
    audit_user_id BIGINT,
    audit_time   TIMESTAMP,
    deleted      SMALLINT     DEFAULT 0,
    create_time  TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    update_time  TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_signup_activity   FOREIGN KEY (activity_id)   REFERENCES volunteer_activity (id),
    CONSTRAINT fk_signup_student    FOREIGN KEY (student_id)    REFERENCES student_info (id),
    CONSTRAINT fk_signup_audit_user FOREIGN KEY (audit_user_id) REFERENCES sys_user (id),
    CONSTRAINT uk_activity_student  UNIQUE (activity_id, student_id)
);

COMMENT ON TABLE  activity_signup              IS '活动报名表';
COMMENT ON COLUMN activity_signup.activity_id  IS '活动ID → volunteer_activity.id';
COMMENT ON COLUMN activity_signup.student_id   IS '学生ID → student_info.id（注意：是学生档案ID，不是 sys_user.id）';
COMMENT ON COLUMN activity_signup.signup_time  IS '报名时间';
COMMENT ON COLUMN activity_signup.status       IS '报名状态：PENDING待审核，APPROVED已通过，REJECTED已驳回，CANCELED已取消，COMPLETED已完成';
COMMENT ON COLUMN activity_signup.audit_remark IS '审核意见';
COMMENT ON COLUMN activity_signup.audit_user_id IS '审核人 → sys_user.id（组织管理员）';
COMMENT ON COLUMN activity_signup.audit_time   IS '审核时间';
COMMENT ON COLUMN activity_signup.deleted      IS '逻辑删除：0未删除，1已删除';

-- -------------------------------------------------------------
-- 13. 签到签退记录表
--     说明：signup_id 唯一 → 一条报名最多一条签到记录
-- -------------------------------------------------------------
CREATE TABLE attendance_record (
    id            BIGSERIAL   PRIMARY KEY,
    signup_id     BIGINT      NOT NULL UNIQUE,
    sign_in_time  TIMESTAMP,
    sign_out_time TIMESTAMP,
    status        VARCHAR(20) DEFAULT 'NOT_SIGNED',
    remark        VARCHAR(255),
    deleted       SMALLINT    DEFAULT 0,
    create_time   TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    update_time   TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_attendance_signup FOREIGN KEY (signup_id) REFERENCES activity_signup (id)
);

COMMENT ON TABLE  attendance_record               IS '签到签退记录表';
COMMENT ON COLUMN attendance_record.signup_id     IS '报名ID → activity_signup.id（唯一，一条报名对应一条签到记录）';
COMMENT ON COLUMN attendance_record.sign_in_time  IS '签到时间';
COMMENT ON COLUMN attendance_record.sign_out_time IS '签退时间';
COMMENT ON COLUMN attendance_record.status        IS '签到状态：NOT_SIGNED未签到，SIGNED_IN已签到，SIGNED_OUT已签退，ABNORMAL异常，ABSENT缺勤';
COMMENT ON COLUMN attendance_record.remark        IS '备注（异常原因等）';
COMMENT ON COLUMN attendance_record.deleted       IS '逻辑删除：0未删除，1已删除';


-- =============================================================
-- 四、时长认证域（vcp-certification）—— 2 张表
-- =============================================================

-- -------------------------------------------------------------
-- 14. 服务时长表
-- -------------------------------------------------------------
CREATE TABLE service_duration (
    id            BIGSERIAL     PRIMARY KEY,
    signup_id     BIGINT        NOT NULL UNIQUE,
    activity_id   BIGINT        NOT NULL,
    student_id    BIGINT        NOT NULL,
    duration      NUMERIC(10,1) DEFAULT 0,
    status        VARCHAR(20)   DEFAULT 'PENDING_SUBMIT',
    submit_time   TIMESTAMP,
    audit_user_id BIGINT,
    audit_time    TIMESTAMP,
    audit_remark  VARCHAR(255),
    deleted       SMALLINT      DEFAULT 0,
    create_time   TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    update_time   TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_duration_signup    FOREIGN KEY (signup_id)   REFERENCES activity_signup (id),
    CONSTRAINT fk_duration_activity  FOREIGN KEY (activity_id) REFERENCES volunteer_activity (id),
    CONSTRAINT fk_duration_student   FOREIGN KEY (student_id)  REFERENCES student_info (id),
    CONSTRAINT fk_duration_audit_user FOREIGN KEY (audit_user_id) REFERENCES sys_user (id)
);

COMMENT ON TABLE  service_duration               IS '服务时长表';
COMMENT ON COLUMN service_duration.signup_id     IS '报名ID → activity_signup.id（唯一，一条报名对应一条时长记录）';
COMMENT ON COLUMN service_duration.activity_id   IS '活动ID → volunteer_activity.id（冗余，便于按活动统计）';
COMMENT ON COLUMN service_duration.student_id    IS '学生ID → student_info.id（冗余，便于按学生/学院统计）';
COMMENT ON COLUMN service_duration.duration      IS '实际服务时长（小时）；由组织管理员依据签到签退记录提交';
COMMENT ON COLUMN service_duration.status        IS '时长状态：PENDING_SUBMIT待提交，PENDING_AUDIT待审核，APPROVED已通过，REJECTED已驳回（由学校管理员终审）';
COMMENT ON COLUMN service_duration.submit_time   IS '提交时间';
COMMENT ON COLUMN service_duration.audit_user_id IS '审核人 → sys_user.id（学校管理员）';
COMMENT ON COLUMN service_duration.audit_time    IS '审核时间';
COMMENT ON COLUMN service_duration.audit_remark  IS '审核意见（驳回原因）';
COMMENT ON COLUMN service_duration.deleted       IS '逻辑删除：0未删除，1已删除';

-- -------------------------------------------------------------
-- 15. 时长审核记录表
--     说明：审核流水按只追加设计，不加 deleted / update_time
-- -------------------------------------------------------------
CREATE TABLE duration_audit (
    id          BIGSERIAL   PRIMARY KEY,
    duration_id BIGINT      NOT NULL,
    auditor_id  BIGINT,
    action      VARCHAR(20),
    remark      VARCHAR(255),
    create_time TIMESTAMP   DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_audit_duration FOREIGN KEY (duration_id) REFERENCES service_duration (id),
    CONSTRAINT fk_audit_auditor  FOREIGN KEY (auditor_id)  REFERENCES sys_user (id)
);

COMMENT ON TABLE  duration_audit             IS '时长审核记录表（每次提交/审核动作留痕）';
COMMENT ON COLUMN duration_audit.duration_id IS '时长记录ID → service_duration.id';
COMMENT ON COLUMN duration_audit.auditor_id  IS '操作人 → sys_user.id';
COMMENT ON COLUMN duration_audit.action      IS '审核动作：SUBMIT提交，APPROVE通过，REJECT驳回（注意与状态值的 APPROVED/REJECTED 不同形）';
COMMENT ON COLUMN duration_audit.remark      IS '备注';


-- =============================================================
-- 五、公益画像域（vcp-portrait）—— 1 张表
-- =============================================================

-- -------------------------------------------------------------
-- 16. 学生公益画像表
-- -------------------------------------------------------------
CREATE TABLE student_profile (
    id                  BIGSERIAL     PRIMARY KEY,
    student_id          BIGINT        NOT NULL UNIQUE,
    total_activities    INT           DEFAULT 0,
    total_duration      NUMERIC(10,1) DEFAULT 0,
    category_preference VARCHAR(255),
    tags                VARCHAR(255),
    portrait_desc       TEXT,
    create_time         TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    update_time         TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_profile_student FOREIGN KEY (student_id) REFERENCES student_info (id)
);

COMMENT ON TABLE  student_profile                     IS '学生公益画像表（每个学生一行，由定时/手动任务重算）';
COMMENT ON COLUMN student_profile.student_id          IS '学生ID → student_info.id（唯一）';
COMMENT ON COLUMN student_profile.total_activities    IS '参与活动次数（按审核通过的报名计）';
COMMENT ON COLUMN student_profile.total_duration      IS '累计志愿时长（小时）；权威值在 student_info.total_duration，此处为画像快照，见 README 待定项';
COMMENT ON COLUMN student_profile.category_preference IS '偏好活动类型（参与最多的分类名）';
COMMENT ON COLUMN student_profile.tags                IS '公益标签，逗号分隔（如"热心志愿者,校园服务型"）；【判定规则尚未确定，见 README 待定项】';
COMMENT ON COLUMN student_profile.portrait_desc       IS '画像描述文本';


-- =============================================================
-- 六、索引
-- =============================================================
--
-- 设计说明（与最初 AI 生成的脚本相比做了删减与补充，理由见 sql/README.md）：
--   · 删除了被 UNIQUE 约束覆盖的冗余索引：sys_user(username)、sys_role(role_code)、
--     student_info(student_no)
--   · 删除了被 uk_activity_student(activity_id, student_id) 最左前缀覆盖的
--     activity_signup(activity_id)
--   · attendance_record(signup_id) 同理被其 UNIQUE 约束覆盖，无需另建
--   · 补上知识库《全局技术规范》建议的复合索引，以及看板统计所需索引
--
-- 被删除的索引并非"错误"，只是重复占用空间与写入开销；如需与旧脚本保持一致可自行加回。
-- -------------------------------------------------------------

-- 活动：按状态筛选、按开始时间排序（活动列表页）
CREATE INDEX idx_activity_status     ON volunteer_activity (status);
CREATE INDEX idx_activity_start_time ON volunteer_activity (start_time);
-- 活动：组织端"本组织的活动"按状态筛选
CREATE INDEX idx_activity_org_status ON volunteer_activity (org_id, status);
-- 活动：看板"本月新增活动数"与活动数量趋势图
CREATE INDEX idx_activity_create_time ON volunteer_activity (create_time);

-- 报名：学生端"我的报名"按状态筛选（student_id 为最左前缀，同时覆盖仅按 student_id 的查询）
CREATE INDEX idx_signup_student_status ON activity_signup (student_id, status);

-- 时长：学校端"待审核时长"列表
CREATE INDEX idx_duration_status         ON service_duration (status);
-- 时长：学生端"我的时长"按状态筛选
CREATE INDEX idx_duration_student_status ON service_duration (student_id, status);
-- 时长：看板"各学院志愿时长排名"需要按学院分组，先按学生定位
CREATE INDEX idx_duration_activity       ON service_duration (activity_id);

-- 学生：学院排名与学院维度统计按学院分组
CREATE INDEX idx_student_college ON student_info (college);

-- 通知：学生端"我的通知"与未读数
CREATE INDEX idx_notification_user ON notification (user_id);

